import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams, useNavigate } from "react-router-dom";
import private_api from "../../server/private_api";

const LecionaAvaliacao = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [cursos, setCursos] = useState([]);
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [novaAvaliacao, setNovaAvaliacao] = useState({
    titulo: "",
    cursoId: "",
    tipo: "escolha_multipla",
    perguntas: [
      {
        texto: "",
        opcoes: ["", "", "", ""],
        respostaCorreta: 0,
      },
    ],
  });

  // Carrega os dados do professor
  useEffect(() => {
    const fetchData = async () => {
      try {
        // Carrega cursos do professor
        const cursosRes = await private_api.get(`/professores/${id}/cursos`);
        setCursos(cursosRes.data);

        // Carrega avaliações do professor
        const avaliacoesRes = await private_api.get(
          `/professores/${id}/avaliacoes`
        );
        setAvaliacoes(avaliacoesRes.data);
      } catch (error) {
        console.error("Erro ao carregar dados:", error);
      }
    };

    fetchData();
  }, [id]);

  // Manipuladores para o formulário de escolha múltipla
  const handleAddPergunta = () => {
    setNovaAvaliacao((prev) => ({
      ...prev,
      perguntas: [
        ...prev.perguntas,
        { texto: "", opcoes: ["", "", "", ""], respostaCorreta: 0 },
      ],
    }));
  };

  const handleRemovePergunta = (index) => {
    if (novaAvaliacao.perguntas.length <= 1) return;
    setNovaAvaliacao((prev) => ({
      ...prev,
      perguntas: prev.perguntas.filter((_, i) => i !== index),
    }));
  };

  const handlePerguntaChange = (index, field, value) => {
    const novasPerguntas = [...novaAvaliacao.perguntas];
    novasPerguntas[index][field] = value;
    setNovaAvaliacao((prev) => ({ ...prev, perguntas: novasPerguntas }));
  };

  const handleOpcaoChange = (perguntaIndex, opcaoIndex, value) => {
    const novasPerguntas = [...novaAvaliacao.perguntas];
    novasPerguntas[perguntaIndex].opcoes[opcaoIndex] = value;
    setNovaAvaliacao((prev) => ({ ...prev, perguntas: novasPerguntas }));
  };

  const handleSubmitAvaliacao = async () => {
    try {
      // Validação básica
      if (!novaAvaliacao.titulo || !novaAvaliacao.cursoId) {
        alert("Preencha todos os campos obrigatórios");
        return;
      }

      // Envia para o backend
      const resposta = await private_api.post("/avaliacoes", {
        ...novaAvaliacao,
        professorId: id,
        dataInicio: new Date().toISOString(),
        dataFim: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // +7 dias
      });

      if (resposta.status === 201) {
        alert("Avaliação criada com sucesso!");
        setShowModal(false);
        // Recarrega as avaliações
        const avaliacoesRes = await private_api.get(
          `/professores/${id}/avaliacoes`
        );
        setAvaliacoes(avaliacoesRes.data);
        // Reseta o formulário
        setNovaAvaliacao({
          titulo: "",
          cursoId: "",
          tipo: "escolha_multipla",
          perguntas: [
            {
              texto: "",
              opcoes: ["", "", "", ""],
              respostaCorreta: 0,
            },
          ],
        });
      }
    } catch (error) {
      console.error("Erro ao criar avaliação:", error);
      alert(`Erro: ${error.response?.data?.error || error.message}`);
    }
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      {/* Cabeçalho e navegação */}
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href={`/lecionalista/${id}`}>
          Cursos
        </a>
        <a className="nav-link" href={`/professoraulas/${id}`}>
          Aulas
        </a>
        <a className="nav-link active" href={`/lecionaavaliacao/${id}`}>
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Avaliações do Professor</h2>

      {/* Botão para criar nova avaliação */}
      <div className="w-75 mb-4 d-flex justify-content-end">
        <button className="btn btn-primary" onClick={() => setShowModal(true)}>
          Criar Nova Avaliação
        </button>
      </div>

      {/* Lista de avaliações existentes */}
      <div className="bg-white p-3 rounded shadow w-75">
        <h4>Minhas Avaliações</h4>
        {avaliacoes.length > 0 ? (
          <table className="table table-bordered">
            <thead>
              <tr>
                <th>Título</th>
                <th>Curso</th>
                <th>Tipo</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {avaliacoes.map((avaliacao, index) => (
                <tr key={index}>
                  <td>{avaliacao.titulo}</td>
                  <td>{avaliacao.curso?.nome || "N/A"}</td>
                  <td>{avaliacao.tipo}</td>
                  <td>
                    <span
                      className={`badge ${
                        new Date(avaliacao.dataFim) > new Date()
                          ? "bg-success"
                          : "bg-secondary"
                      }`}
                    >
                      {new Date(avaliacao.dataFim) > new Date()
                        ? "Ativa"
                        : "Encerrada"}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <div className="alert alert-info">Nenhuma avaliação criada ainda</div>
        )}
      </div>

      {/* Modal para criação de avaliação de escolha múltipla */}
      {showModal && (
        <div
          className="modal show d-block"
          style={{ backgroundColor: "rgba(0,0,0,0.5)" }}
        >
          <div className="modal-dialog modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">
                  Criar Avaliação de Escolha Múltipla
                </h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <label className="form-label">Título da Avaliação*</label>
                  <input
                    type="text"
                    className="form-control"
                    value={novaAvaliacao.titulo}
                    onChange={(e) =>
                      setNovaAvaliacao({
                        ...novaAvaliacao,
                        titulo: e.target.value,
                      })
                    }
                  />
                </div>

                <div className="mb-3">
                  <label className="form-label">Curso*</label>
                  <select
                    className="form-select"
                    value={novaAvaliacao.cursoId}
                    onChange={(e) =>
                      setNovaAvaliacao({
                        ...novaAvaliacao,
                        cursoId: e.target.value,
                      })
                    }
                  >
                    <option value="">Selecione um curso</option>
                    {cursos.map((curso) => (
                      <option key={curso.id} value={curso.id}>
                        {curso.nome}
                      </option>
                    ))}
                  </select>
                </div>

                <h5 className="mt-4">Perguntas</h5>
                {novaAvaliacao.perguntas.map((pergunta, pIndex) => (
                  <div key={pIndex} className="card mb-3">
                    <div className="card-header d-flex justify-content-between">
                      <span>Pergunta {pIndex + 1}</span>
                      <button
                        className="btn btn-sm btn-danger"
                        onClick={() => handleRemovePergunta(pIndex)}
                        disabled={novaAvaliacao.perguntas.length <= 1}
                      >
                        Remover
                      </button>
                    </div>
                    <div className="card-body">
                      <div className="mb-3">
                        <label className="form-label">Texto da Pergunta*</label>
                        <input
                          type="text"
                          className="form-control"
                          value={pergunta.texto}
                          onChange={(e) =>
                            handlePerguntaChange(
                              pIndex,
                              "texto",
                              e.target.value
                            )
                          }
                        />
                      </div>

                      <label className="form-label">Opções de Resposta*</label>
                      {pergunta.opcoes.map((opcao, oIndex) => (
                        <div key={oIndex} className="input-group mb-2">
                          <div className="input-group-text">
                            <input
                              type="radio"
                              name={`resposta-${pIndex}`}
                              checked={pergunta.respostaCorreta === oIndex}
                              onChange={() =>
                                handlePerguntaChange(
                                  pIndex,
                                  "respostaCorreta",
                                  oIndex
                                )
                              }
                            />
                          </div>
                          <input
                            type="text"
                            className="form-control"
                            placeholder={`Opção ${oIndex + 1}`}
                            value={opcao}
                            onChange={(e) =>
                              handleOpcaoChange(pIndex, oIndex, e.target.value)
                            }
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                ))}

                <button
                  className="btn btn-outline-primary mt-2"
                  onClick={handleAddPergunta}
                >
                  Adicionar Pergunta
                </button>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowModal(false)}
                >
                  Cancelar
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleSubmitAvaliacao}
                >
                  Criar Avaliação
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default LecionaAvaliacao;
